package jp.tapmarker;
import java.io.*;import java.util.*;import java.util.zip.*;

/** Ordinary dialog holdouts plus the previously working virtual reward screen. */
public final class FarmDialogReplayTest {
 static int checks;static Map<String,float[]> canonical,evidence;
 static Map<String,VirtualPresetProfileTest.Image> images=new LinkedHashMap<>();
 static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static void load()throws Exception{
  canonical=VirtualPresetProfileTest.canonical("tests/farm-replay.bin");VirtualRecoveryReplayTest.load();VirtualRecoveryReplayTest.layoutEvidence();evidence=new HashMap<>(VirtualRecoveryReplayTest.evidence);
  try(DataInputStream in=new DataInputStream(new FileInputStream("tests/farm-dialog-references.bin"))){evidence.putAll(UsagiPresetTest.read(in));check(in.read()==-1,"complete mask reference data");}evidence.putAll(VirtualPresetProfileTest.canonical("tests/farm-close-20261013-reference.bin"));
  try(DataInputStream in=new DataInputStream(new GZIPInputStream(new FileInputStream("tests/farm-dialog-replay.bin.gz")))){int n=in.readInt();for(int i=0;i<n;i++)images.put(in.readUTF(),new VirtualPresetProfileTest.Image(in));check(n==12&&in.read()==-1,"twelve complete held-out video frames");}
 }
 static final class Run {
  final PhaseEngine e=new PhaseEngine();final AdaptiveLayout layout;
  Run(){FarmPreset.install(e,canonical);e.strictRuntime=true;layout=AdaptiveLayout.install(e,FarmPreset.APP,canonical,evidence);check(layout!=null,"farm runtime layout exists");}
  Map<String,float[]> sample(String state,int width,int height,RegionSampler.Pixels pixels,long now){e.enter(FarmPreset.P+state,0);return layout.sampleRelative(e.activeRegions(),width,height,pixels,now);}
 }
 static RegionSampler.Pixels resize(VirtualPresetProfileTest.Image im,int width,int height,boolean smooth){return (x,y)->{
  if(!smooth)return im.get(Math.min(im.width-1,x*im.width/width),Math.min(im.height-1,y*im.height/height));
  float px=(x+.5f)*im.width/width-.5f,py=(y+.5f)*im.height/height-.5f;int x0=Math.max(0,Math.min(im.width-1,(int)Math.floor(px))),y0=Math.max(0,Math.min(im.height-1,(int)Math.floor(py))),x1=Math.min(im.width-1,x0+1),y1=Math.min(im.height-1,y0+1);float fx=Math.max(0,px-x0),fy=Math.max(0,py-y0);int color=0xff000000;
  for(int shift:new int[]{16,8,0}){float a=((im.get(x0,y0)>>shift&255)*(1-fx)+(im.get(x1,y0)>>shift&255)*fx),b=((im.get(x0,y1)>>shift&255)*(1-fx)+(im.get(x1,y1)>>shift&255)*fx);color|=Math.round(a*(1-fy)+b*fy)<<shift;}return color;
 };}
 static PhaseEngine.Watch confirm(Run r,Map<String,float[]> s){r.e.observe(s,7000);check(r.e.poll()==null,"first dialog observation waits even after timeout");r.e.observe(s,7200);return r.e.poll();}
 static void dialogs(){
  for(String[] row:new String[][]{{"65.5","reward","close","check"},{"66.2","reward","close","check"},{"66.4","reward","close","check"},{"69.8","bonus","start","verify"},{"70.2","bonus","start","verify"},{"70.4","bonus","start","verify"}}){
   Run r=new Run();VirtualPresetProfileTest.Image im=images.get(row[0]);Map<String,float[]> s=r.sample(row[1],im.width,im.height,im,1000);PhaseEngine.Watch w=confirm(r,s);check(w!=null&&w.action==PhaseEngine.CENTER&&w.regionId.equals(FarmPreset.P+row[2])&&w.nextPhase.equals(FarmPreset.P+row[3]),"held-out ordinary dialog input: "+Arrays.toString(row)+" / "+r.e.diagnostic);float[] p=r.layout.pointRelative(w,s,im.width,im.height);float[][] anchors=row[2].equals("close")?FarmDialogEvidence.CLOSE:FarmDialogEvidence.START;float[] box=anchors[1];check(p!=null&&p[0]>box[0]*im.width&&p[0]<box[2]*im.width&&p[1]>box[1]*im.height&&p[1]<box[3]*im.height,"tap is inside the visible individual label, away from the CM button");check(r.e.confirmsAction(w,r.e.current,r.e.epoch,s),"dialog input confirms its latest evidence");
   for(String state:new String[]{"main","check","ad","verify"}){Run c=new Run();Map<String,float[]> t=c.sample(state,im.width,im.height,im,1000);PhaseEngine.Watch found=confirm(c,t);check(found!=null&&found.nextPhase.equals(FarmPreset.P+row[1]),"dialog classifies from "+state+" / "+row[0]);}
  }
 }
 static void scaled(){
  for(int[] size:new int[][]{{444,994},{540,1140},{540,1211},{720,1520},{1080,2280}})for(boolean smooth:new boolean[]{false,true})for(String[] row:new String[][]{{"66.2","reward","close"},{"70.2","bonus","start"}}){Run r=new Run();VirtualPresetProfileTest.Image im=images.get(row[0]);Map<String,float[]> s=r.sample(row[1],size[0],size[1],resize(im,size[0],size[1],smooth),1000);PhaseEngine.Watch w=confirm(r,s);check(w!=null&&w.action==PhaseEngine.CENTER&&w.regionId.equals(FarmPreset.P+row[2]),"resized dialog: "+Arrays.toString(size)+" smooth="+smooth+" / "+row[0]+" / "+r.e.diagnostic);float[] p=r.layout.pointRelative(w,s,size[0],size[1]);check(p!=null&&Math.abs(p[0]/size[0]-(row[2].equals("close")?.5f:.51f))<.05f&&Math.abs(p[1]/size[1]-(row[2].equals("close")?.662f:.8405f))<.025f,"resized input stays inside the button");}
 }
 static void negatives(){
  for(Map.Entry<String,VirtualPresetProfileTest.Image> row:images.entrySet()){VirtualPresetProfileTest.Image im=row.getValue();FarmDialogEvidence d=new FarmDialogEvidence(evidence);boolean close=Arrays.asList("65.5","66.2","66.4").contains(row.getKey()),start=Arrays.asList("69.8","70.2","70.4").contains(row.getKey());for(String id:new String[]{"close","start"})check(d.locate(FarmPreset.P+id,im.width,im.height,im,1000,new HashMap<>())==(id.equals("close")?close:start),"game, ad and automatic chest animation do not become dialog controls: "+row.getKey()+" / "+id);}
  for(String[] row:new String[][]{{"66.2","close"},{"70.2","start"}}){VirtualPresetProfileTest.Image im=images.get(row[0]);float[][] boxes=row[1].equals("close")?FarmDialogEvidence.CLOSE:FarmDialogEvidence.START;for(float[] box:boxes){int[] b=RegionMath.bounds(box,im.width,im.height);RegionSampler.Pixels hidden=(x,y)->x>=b[0]&&x<b[2]&&y>=b[1]&&y<b[3]?0xff555555:im.get(x,y);check(!new FarmDialogEvidence(evidence).locate(FarmPreset.P+row[1],im.width,im.height,hidden,1000,new HashMap<>()),"both heading and button are required: "+row[1]+" / "+Arrays.toString(box));}}
  for(String name:new String[]{"farm-main","farm-main-pressed","farm-ad-left","farm-ad-right","usagi-main","usagi-ad-left"}){VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get(name);for(String id:new String[]{"close","start"})check(!new FarmDialogEvidence(evidence).locate(FarmPreset.P+id,im.width,im.height,im,1000,new HashMap<>()),"previous gameplay, ads and other app never authorize these controls: "+name+" / "+id);}
 }
 static void oldAndMoved(){
  for(String name:new String[]{"farm-reward","farm-reward-holdout"}){Run r=new Run();VirtualPresetProfileTest.Image im=VirtualRecoveryReplayTest.images.get(name);Map<String,float[]> s=r.sample("reward",im.width,im.height,im,1000);PhaseEngine.Watch w=confirm(r,s);check(w!=null&&w.action==PhaseEngine.CENTER,"working virtual close recognition retained: "+name);float[] p=r.layout.pointRelative(w,s,im.width,im.height);check(p!=null&&p[1]/im.height>.565f&&p[1]/im.height<.613f,"virtual reward tap retains its own UI layout");}
  for(String[] row:new String[][]{{"66.2","reward"},{"70.2","bonus"}}){Run r=new Run();VirtualPresetProfileTest.Image im=images.get(row[0]);int width=1600,height=1800,left=650,top=70;RegionSampler.Pixels desktop=(x,y)->x>=left&&x<left+im.width&&y>=top&&y<top+im.height?im.get(x-left,y-top):0xff223344;r.e.enter(FarmPreset.P+row[1],0);Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),width,height,desktop,1000,new int[]{left,top,left+im.width,top+im.height});PhaseEngine.Watch w=confirm(r,s);check(w!=null&&w.action==PhaseEngine.CENTER,"moved desktop window matches dialog evidence");float[] p=r.layout.pointRelative(w,s,width,height);check(p!=null&&Math.abs((p[0]-left)/im.width-.5f)<.05f&&Math.abs((p[1]-top)/im.height-(row[1].equals("reward")?.662f:.8405f))<.025f,"button point includes exact desktop window offset");check(r.layout.pointRelative(w,s,width+1,height)==null,"frame resize invalidates old window metadata");}
 }
 static void customTreasure(){
  PhaseEngine e=new PhaseEngine();FarmPreset.install(e,canonical);e.strictRuntime=true;VirtualPresetProfileTest.Image im=images.get("20");PhaseEngine.Region region=e.regions.get(FarmPreset.P+"chest-open");region.bounds=new float[]{.70f,.08f,.78f,.11f};PhaseEngine.Watch custom=e.rule(FarmPreset.P+"chest-chest-open");custom.reference=RegionSampler.sample(im.width,im.height,region.bounds,im);AdaptiveLayout layout=AdaptiveLayout.install(e,FarmPreset.APP,canonical,evidence);layout.relativeEnabled=false;e.enter(FarmPreset.P+"chest",0);Map<String,float[]> s=layout.sampleRelative(e.activeRegions(),im.width,im.height,im,1000);e.observe(s,7000);check(e.poll()==null,"first custom treasure image waits");e.observe(s,7200);PhaseEngine.Watch w=e.poll();check(w==custom&&w.action==PhaseEngine.CENTER,"user-recorded treasure image remains eligible without an accessibility label");float[] p=layout.pointRelative(w,s,im.width,im.height);check(p!=null&&Math.abs(p[0]/im.width-.74f)<.001f&&Math.abs(p[1]/im.height-.095f)<.001f,"edited treasure target keeps the user's recorded image position");
 }
 public static void main(String[] args)throws Exception{load();dialogs();scaled();negatives();oldAndMoved();customTreasure();System.out.println("FarmDialogReplayTest: "+checks+" checks passed; held-out 6612 pixels, five resized geometries, independent dialog anchors and prior virtual layout; F-52A/Chromebook device input not tested");}
}
